    public static func ==(lhs: TaskViewMembership, rhs: TaskViewMembership) -> Bool {
        if lhs.isUnfiled != rhs.isUnfiled {
            return false
        }
        if lhs.isInboxMember != rhs.isInboxMember {
            return false
        }
        if lhs.inTriageBand != rhs.inTriageBand {
            return false
        }
        if lhs.isOnToday != rhs.isOnToday {
            return false
        }
        if lhs.inTodayInbox != rhs.inTodayInbox {
            return false
        }
        if lhs.daysOnToday != rhs.daysOnToday {
            return false
        }
        if lhs.matchesToday != rhs.matchesToday {
            return false
        }
        if lhs.matchesInbox != rhs.matchesInbox {
            return false
        }
        if lhs.matchesUpcoming != rhs.matchesUpcoming {
            return false
        }
        if lhs.matchesAnytime != rhs.matchesAnytime {
            return false
        }
        if lhs.dueState != rhs.dueState {
            return false
        }
        if lhs.deadlineRed != rhs.deadlineRed {
            return false
        }
        if lhs.upcomingDay != rhs.upcomingDay {
            return false
        }
        if lhs.arrivedOnOwn != rhs.arrivedOnOwn {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(isUnfiled)
        hasher.combine(isInboxMember)
        hasher.combine(inTriageBand)
        hasher.combine(isOnToday)
        hasher.combine(inTodayInbox)
        hasher.combine(daysOnToday)
        hasher.combine(matchesToday)
        hasher.combine(matchesInbox)
        hasher.combine(matchesUpcoming)
        hasher.combine(matchesAnytime)
        hasher.combine(dueState)
        hasher.combine(deadlineRed)
        hasher.combine(upcomingDay)
        hasher.combine(arrivedOnOwn)
    }
}



